void book_room(Transaction& tx, RoomId room, DateRange stay) {
    auto rollback = scope_exit{[&] { tx.rollback(); }};   // fires on any exit
    if (!tx.room_available(room, stay)) throw NotAvailable{room};
    tx.insert_booking(room, stay, tx.rate_for(room, stay));
    tx.commit();
    rollback.release();        // disarm: commit() must be the last fallible step
}
